"""Tiny restaurant ops core: inventory counts, par-level orders, food-cost drift alerts."""
from dataclasses import dataclass, field

@dataclass
class Item:
    name: str
    unit_cost: float
    par: float          # target on-hand quantity
    supplier: str

@dataclass
class Ops:
    items: dict = field(default_factory=dict)
    counts: dict = field(default_factory=dict)

    def add_item(self, item: Item):
        self.items[item.name] = item

    def count(self, name: str, on_hand: float):
        if name not in self.items:
            raise KeyError(f"unknown item: {name}")
        self.counts[name] = on_hand

    def supplier_orders(self):
        """Order enough to bring each counted item back to par, grouped by supplier."""
        orders = {}
        for name, on_hand in self.counts.items():
            it = self.items[name]
            need = max(0.0, it.par - on_hand)
            if need > 0:
                orders.setdefault(it.supplier, []).append((name, need))
        return orders

    def food_cost_alert(self, food_sales: float, food_cost: float, target_pct=0.30):
        """Flag when actual food cost % exceeds target."""
        if food_sales <= 0:
            return None
        pct = food_cost / food_sales
        if pct > target_pct:
            return f"Food cost {pct:.1%} is above target {target_pct:.0%}"
        return None

if __name__ == "__main__":
    ops = Ops()
    ops.add_item(Item("chicken thigh (lb)", 2.10, 40, "Valley Foods"))
    ops.add_item(Item("rice (lb)", 0.60, 50, "Valley Foods"))
    ops.add_item(Item("tortillas (pack)", 1.25, 20, "Bay Produce"))
    ops.count("chicken thigh (lb)", 12)
    ops.count("rice (lb)", 45)
    ops.count("tortillas (pack)", 4)
    for sup, lines in ops.supplier_orders().items():
        print(sup)
        for name, qty in lines:
            print(f"  {name}: order {qty:g}")
    print(ops.food_cost_alert(food_sales=4200, food_cost=1550) or "Food cost OK")
EOF
